Extensions.ExtractScript:
param(
    [xml] $Document
);

foreach( $file in $Document.unattend.Extensions.File ) {
    # Resolve environment variables (if any) in the destination file path.
    $path = [System.Environment]::ExpandEnvironmentVariables( $file.GetAttribute( 'path' ) );

    # Ensure the parent directory exists before writing.
    mkdir -Path( $path | Split-Path -Parent ) -ErrorAction 'SilentlyContinue';

    # Choose appropriate encoding by file extension (UTF-8 w/ BOM for PS1/XML; UTF-16 LE for REG/VBS/JS).
    $encoding = switch( [System.IO.Path]::GetExtension( $path ) ) {
        { $_ -in '.ps1', '.xml' } { [System.Text.Encoding]::UTF8; }
        { $_ -in '.reg', '.vbs', '.js' } { [System.Text.UnicodeEncoding]::new( $false, $true ); }
        default { [System.Text.Encoding]::Default; }
    };

    # Write file bytes with BOM preamble.
    $bytes = $encoding.GetPreamble() + $encoding.GetBytes( $file.InnerText.Trim() );
    [System.IO.File]::WriteAllBytes( $path, $bytes );
}

Extensions.File:
# Provisioned AppX package DisplayNames to remove for all users.
# Tip: Prefix any line with '#' if you want to keep that application.
$selectors = @(
	# --- Productivity, Office and Communication ---
	'Microsoft.MicrosoftOfficeHub';          # Microsoft 365 (Office) Hub
	'Microsoft.Office.OneNote';              # OneNote for Windows 10
	'Microsoft.OutlookForWindows';           # Outlook (New)
	'microsoft.windowscommunicationsapps';   # Legacy Mail and Calendar
	'Microsoft.People';                      # People
	'Microsoft.PowerAutomateDesktop';        # Power Automate Desktop
	'Microsoft.SkypeApp';                    # Skype
	'MicrosoftTeams';                        # Teams (Work or School / Chat)
	'MSTeams';                               # Teams (New / Consumer)
	'Microsoft.Todos';                       # Microsoft To Do
	'Microsoft.MicrosoftStickyNotes';        # Sticky Notes

	# --- AI, Assistants and Help ---
	'Microsoft.Copilot';                     # Microsoft Copilot app
	'Microsoft.365Copilot';                  # Microsoft 365 Copilot
	'Microsoft.549981C3F5F10';               # Cortana
	'Microsoft.GetHelp';                     # Get Help
	'Microsoft.Getstarted';                  # Tips / Get Started
	'Microsoft.WindowsFeedbackHub';          # Feedback Hub
	'MicrosoftCorporationII.QuickAssist';    # Quick Assist
	'Microsoft.Windows.DevHome';             # Dev Home

	# --- Media, News, Weather and Utilities ---
	'Clipchamp.Clipchamp';                   # Clipchamp Video Editor
	'Microsoft.Microsoft3DViewer';           # 3D Viewer
	'Microsoft.MixedReality.Portal';         # Mixed Reality Portal
	'Microsoft.WindowsCamera';               # Camera
	'Microsoft.WindowsAlarms';               # Clock (Alarms and Clock)
	'Microsoft.WindowsSoundRecorder';        # Sound Recorder
	'Microsoft.WindowsMaps';                 # Maps
	'Microsoft.BingNews';                    # Microsoft News
	'Microsoft.BingWeather';                 # Weather
	'Microsoft.ZuneMusic';                   # Windows Media Player (formerly Groove Music)
	'Microsoft.ZuneVideo';                   # Movies and TV

	# --- Account, Family, Store and Phone Integration ---
	'MicrosoftCorporationII.MicrosoftFamily';# Microsoft Family Safety
	'Microsoft.Wallet';                      # Microsoft Pay / Wallet
	'Microsoft.StorePurchaseApp';            # Store Purchase App (Note: Comment out if you install apps via MS Store)
	'Microsoft.YourPhone';                   # Phone Link
	'MicrosoftWindows.CrossDevice';          # Cross-Device Experience Host (Phone Link)

	# --- Gaming and Xbox Ecosystem ---
	'Microsoft.MicrosoftSolitaireCollection';# Microsoft Solitaire Collection
	'Microsoft.Edge.GameAssist';             # Edge Game Assist
	'Microsoft.GamingApp';                   # Xbox App (Modern)
	'Microsoft.XboxApp';                     # Xbox Console Companion (Legacy)
	'Microsoft.Xbox.TCUI';                   # Xbox Live In-Game Experience
	'Microsoft.XboxGameOverlay';             # Xbox Game Bar Plugin
	'Microsoft.XboxGamingOverlay';           # Xbox Game Bar
	'Microsoft.XboxIdentityProvider';        # Xbox Identity Provider
	'Microsoft.XboxSpeechToTextOverlay';     # Xbox Game Speech Window
);

# Enumerate all currently provisioned AppX packages in the OS image.
$getCommand = {
  Get-AppxProvisionedPackage -Online;
};

# Match exact package DisplayName.
$filterCommand = {
  $_.DisplayName -eq $selector;
};

# Remove matched provisioned packages for all current and future users.
$removeCommand = {
  [CmdletBinding()]
  param(
    [Parameter( Mandatory, ValueFromPipeline )]
    $InputObject
  );
  process {
    $InputObject | Remove-AppxProvisionedPackage -AllUsers -Online -ErrorAction 'Continue';
  }
};

$type = 'Package';
$installed = & $getCommand;

foreach( $selector in $selectors ) {
	$result = [ordered] @{
		Selector = $selector;
	};
	if( $found = $installed | Where-Object -FilterScript $filterCommand ) {
		$result.Output = $found | & $removeCommand;
		if( $? ) {
			$result.Message = "${type} removed.";
		} else {
			$result.Message = "${type} not removed.";
			$result.Error = $Error[0];
		}
	} else {
		$result.Message = "${type} not installed.";
	}
	# Output structured JSON line to Specialize.log for easy troubleshooting.
	$result | ConvertTo-Json -Depth 3 -Compress;
}

# Windows Capabilities (Features on Demand) to remove.
# Only the prefix before '~' is matched (version/language suffixes are handled automatically).
$selectors = @(
	# --- Input, Speech and Accessibility Add-ons ---
	'Language.Handwriting';                  # Handwriting recognition
	'Language.Speech';                       # Speech recognition
	'Language.TextToSpeech';                 # Text-to-speech voices
	'MathRecognizer';                        # Math Input Panel

	# --- Biometrics (Remove if not using IR face unlock) ---
	'Hello.Face.18967';                      # Windows Hello Face
	'Hello.Face.Migration.18967';            # Windows Hello Face Migration
	'Hello.Face.20134';                      # Windows Hello Face (newer builds)

	# --- Legacy and Unused Utilities ---
	'OneCoreUAP.OneSync';                    # Mail, Contacts and Calendar sync engine
	'Microsoft.Windows.PowerShell.ISE';      # Legacy PowerShell ISE
	'App.Support.QuickAssist';               # Quick Assist capability
	'App.StepsRecorder';                     # Steps Recorder (deprecated)
	'Media.WindowsMediaPlayer';              # Legacy Windows Media Player
	'Microsoft.Windows.WordPad';             # WordPad (deprecated)
);

# Query all currently installed Windows Capabilities.
$getCommand = {
  Get-WindowsCapability -Online | Where-Object -Property 'State' -NotIn -Value @(
    'NotPresent';
    'Removed';
  );
};

# Match the capability base name before the '~' delimiter.
$filterCommand = {
  ($_.Name -split '~')[0] -eq $selector;
};

# Uninstall the matched capability.
$removeCommand = {
  [CmdletBinding()]
  param(
    [Parameter( Mandatory, ValueFromPipeline )]
    $InputObject
  );
  process {
    $InputObject | Remove-WindowsCapability -Online -ErrorAction 'Continue';
  }
};

$type = 'Capability';
$installed = & $getCommand;

foreach( $selector in $selectors ) {
	$result = [ordered] @{
		Selector = $selector;
	};
	if( $found = $installed | Where-Object -FilterScript $filterCommand ) {
		$result.Output = $found | & $removeCommand;
		if( $? ) {
			$result.Message = "${type} removed.";
		} else {
			$result.Message = "${type} not removed.";
			$result.Error = $Error[0];
		}
	} else {
		$result.Message = "${type} not installed.";
	}
	$result | ConvertTo-Json -Depth 3 -Compress;
}

# Windows Optional Features to disable and remove payload for.
$selectors = @(
	'MediaPlayback';                         # Legacy Windows Media Playback components
	'MicrosoftWindowsPowerShellV2Root';      # Legacy PowerShell 2.0 engine (security hardening)
	'Microsoft-RemoteDesktopConnection';     # Remote Desktop Connection client feature (if present)
	'Recall';                                # Windows Recall AI snapshot feature
);

# Query all currently enabled Optional Features.
$getCommand = {
  Get-WindowsOptionalFeature -Online | Where-Object -Property 'State' -NotIn -Value @(
    'Disabled';
    'DisabledWithPayloadRemoved';
  );
};

# Match exact FeatureName.
$filterCommand = {
  $_.FeatureName -eq $selector;
};

# Disable the feature and strip its local payload without forcing a reboot.
$removeCommand = {
  [CmdletBinding()]
  param(
    [Parameter( Mandatory, ValueFromPipeline )]
    $InputObject
  );
  process {
    $InputObject | Disable-WindowsOptionalFeature -Online -Remove -NoRestart -ErrorAction 'Continue';
  }
};

$type = 'Feature';
$installed = & $getCommand;

foreach( $selector in $selectors ) {
	$result = [ordered] @{
		Selector = $selector;
	};
	if( $found = $installed | Where-Object -FilterScript $filterCommand ) {
		$result.Output = $found | & $removeCommand;
		if( $? ) {
			$result.Message = "${type} removed.";
		} else {
			$result.Message = "${type} not removed.";
			$result.Error = $Error[0];
		}
	} else {
		$result.Message = "${type} not installed.";
	}
	$result | ConvertTo-Json -Depth 3 -Compress;
}

# Machine-wide configuration tasks executed sequentially during the specialize pass.
$scripts = @(
	# =========================================================================
	# 1. OOBE AND ACCOUNT SETUP
	# =========================================================================
	{
		# Allow completing OOBE offline without forcing a Microsoft Account ("I don't have internet").
		reg.exe add "HKLM\SOFTWARE\Microsoft\Windows\CurrentVersion\OOBE" /v BypassNRO /t REG_DWORD /d 1 /f;
	};
	{
		# Prevent local user passwords from ever expiring.
		net.exe accounts /maxpwage:UNLIMITED;
	};

	# =========================================================================
	# 2. BLOATWARE, ONEDRIVE AND OOBE AUTO-INSTALL REMOVAL
	# =========================================================================
	{
		# Block OOBE from automatically downloading/installing Dev Home.
		Remove-Item -LiteralPath 'Registry::HKLM\Software\Microsoft\WindowsUpdate\Orchestrator\UScheduler_Oobe\DevHomeUpdate' -Force -ErrorAction 'SilentlyContinue';
	};
	{
		# Block OOBE from automatically downloading/installing the new Outlook app.
		Remove-Item -LiteralPath 'Registry::HKLM\Software\Microsoft\WindowsUpdate\Orchestrator\UScheduler_Oobe\OutlookUpdate' -Force -ErrorAction 'SilentlyContinue';
	};
	{
		# Prevent automatic installation of the consumer Microsoft Teams (Chat) app.
		reg.exe add "HKLM\SOFTWARE\Microsoft\Windows\CurrentVersion\Communications" /v ConfigureChatAutoInstall /t REG_DWORD /d 0 /f;
	};
	{
		# Delete OneDrive installers and default Start Menu shortcut before any user profile is created.
		@(
		  'C:\Users\Default\AppData\Roaming\Microsoft\Windows\Start Menu\Programs\OneDrive.lnk';
		  'C:\Windows\System32\OneDriveSetup.exe';
		  'C:\Windows\SysWOW64\OneDriveSetup.exe';
		) | Where-Object -FilterScript { [System.IO.File]::Exists( $_ ); } | Remove-Item -Verbose -ErrorAction 'Continue';
	};
	{
		# Disable OneDrive file synchronization at machine policy level.
		reg.exe add "HKLM\SOFTWARE\Policies\Microsoft\Windows\OneDrive" /v DisableFileSyncNGSC /t REG_DWORD /d 1 /f;
	};
	{
		# Run AppX package removal script.
		& 'C:\Windows\Setup\Scripts\RemovePackage.ps1';
	};
	{
		# Run Windows Capability (FoD) removal script.
		& 'C:\Windows\Setup\Scripts\RemoveCapability.ps1';
	};
	{
		# Run Windows Optional Feature removal script.
		& 'C:\Windows\Setup\Scripts\RemoveFeature.ps1';
	};

	# =========================================================================
	# 3. START MENU, TASKBAR AND SEARCH POLICIES
	# =========================================================================
	{
		# Disable Widgets / News and Interests on the taskbar (machine-wide policy).
		reg.exe add "HKLM\SOFTWARE\Policies\Microsoft\Dsh" /v AllowNewsAndInterests /t REG_DWORD /d 0 /f;
	};
	{
		# Start with an empty pinned apps list in the Start Menu (removes WhatsApp, LinkedIn, Solitaire, etc.).
		# Check existence before creating the key so existing values are never wiped.
		$startPolicyPath = 'Registry::HKLM\SOFTWARE\Microsoft\PolicyManager\current\device\Start';
		if( -not ( Test-Path -LiteralPath $startPolicyPath ) ) {
			New-Item -Path $startPolicyPath -Force | Out-Null;
		}
		Set-ItemProperty -LiteralPath $startPolicyPath -Name 'ConfigureStartPins' -Type 'String' -Value '{"pinnedList":[]}' -Force;
		Set-ItemProperty -LiteralPath $startPolicyPath -Name 'ConfigureStartPins_ProviderSet' -Type 'DWord' -Value 1 -Force;
	};
	{
		# Keep Search Highlights (Quick Searches) and Web/Cloud Search enabled using official GPO values.
		# Note: HideRecommendedSection is intentionally omitted so Top Apps tracking works properly.
		reg.exe add "HKLM\SOFTWARE\Policies\Microsoft\Windows\Windows Search" /v EnableDynamicContentInWSB /t REG_DWORD /d 1 /f;
		reg.exe add "HKLM\SOFTWARE\Policies\Microsoft\Windows\Windows Search" /v AllowCloudSearch /t REG_DWORD /d 1 /f;
		reg.exe add "HKLM\SOFTWARE\Policies\Microsoft\Windows\Windows Search" /v ConnectedSearchUseWeb /t REG_DWORD /d 1 /f;
		reg.exe add "HKLM\SOFTWARE\Policies\Microsoft\Windows\Windows Search" /v DisableWebSearch /t REG_DWORD /d 0 /f;
	};

	# =========================================================================
	# 4. PRIVACY, TELEMETRY, AI AND STORE POLICIES
	# =========================================================================
	{
		# Disable automatic background app updates/downloads from Microsoft Store (2 = Off, 4 = On).
		reg.exe add "HKLM\SOFTWARE\Policies\Microsoft\WindowsStore" /v AutoDownload /t REG_DWORD /d 2 /f;
	};
	{
		# Limit diagnostic data to Required only (1 = Required/Basic, lowest supported level on Home/Pro).
		reg.exe add "HKLM\SOFTWARE\Policies\Microsoft\Windows\DataCollection" /v AllowTelemetry /t REG_DWORD /d 1 /f;
	};
	{
		# Disable Microsoft consumer experiences and suggested apps (Enterprise/Edu policy; Home is handled via ContentDeliveryManager).
		reg.exe add "HKLM\SOFTWARE\Policies\Microsoft\Windows\CloudContent" /v DisableWindowsConsumerFeatures /t REG_DWORD /d 1 /f;
	};
	{
		# Disable tailored tips and ads based on diagnostic data.
		reg.exe add "HKLM\SOFTWARE\Policies\Microsoft\Windows\CloudContent" /v DisableTailoredExperiencesWithDiagnosticData /t REG_DWORD /d 1 /f;
	};
	{
		# Disable Windows tips, tricks, and Soft Landing notifications.
		reg.exe add "HKLM\SOFTWARE\Policies\Microsoft\Windows\CloudContent" /v DisableSoftLanding /t REG_DWORD /d 1 /f;
	};
	{
		# Disable the Advertising ID machine-wide.
		reg.exe add "HKLM\SOFTWARE\Policies\Microsoft\Windows\AdvertisingInfo" /v DisabledByGroupPolicy /t REG_DWORD /d 1 /f;
	};
	{
		# Disable Windows Copilot (machine-wide policy).
		reg.exe add "HKLM\SOFTWARE\Policies\Microsoft\Windows\WindowsCopilot" /v TurnOffWindowsCopilot /t REG_DWORD /d 1 /f;
	};
	{
		# Disable Windows AI data analysis (Recall / snapshot analysis).
		reg.exe add "HKLM\SOFTWARE\Policies\Microsoft\Windows\WindowsAI" /v DisableAIDataAnalysis /t REG_DWORD /d 1 /f;
	};
	{
		# Disable Windows Error Reporting (Group Policy and local system key).
		reg.exe add "HKLM\SOFTWARE\Policies\Microsoft\Windows\Windows Error Reporting" /v Disabled /t REG_DWORD /d 1 /f;
		reg.exe add "HKLM\SOFTWARE\Microsoft\Windows\Windows Error Reporting" /v Disabled /t REG_DWORD /d 1 /f;
	};
	{
		# Restrict Windows Update Delivery Optimization to HTTP only (0 = No P2P bandwidth sharing).
		reg.exe add "HKLM\SOFTWARE\Policies\Microsoft\Windows\DeliveryOptimization" /v DODownloadMode /t REG_DWORD /d 0 /f;
	};
	{
		# Skip Microsoft Edge first-run welcome wizard and sign-in prompts.
		reg.exe add "HKLM\SOFTWARE\Policies\Microsoft\Edge" /v HideFirstRunExperience /t REG_DWORD /d 1 /f;
	};

	# =========================================================================
	# 5. DEVELOPER AND SYSTEM BEHAVIOR
	# =========================================================================
	{
		# Remove the legacy 260-character MAX_PATH limit (important for Node/npm/composer/Git repos).
		reg.exe add "HKLM\SYSTEM\CurrentControlSet\Control\FileSystem" /v LongPathsEnabled /t REG_DWORD /d 1 /f;
	};
	{
		# Disable Fast Startup for cleaner cold boots and dual-boot/driver stability (0 = Off, 1 = On).
		reg.exe add "HKLM\SYSTEM\CurrentControlSet\Control\Session Manager\Power" /v HiberbootEnabled /t REG_DWORD /d 0 /f;
	};
);

# Execute each block with timing and capture all streams to Specialize.log.
& {
  [float] $complete = 0;
  [float] $increment = 100 / $scripts.Count;
  foreach( $script in $scripts ) {
    Write-Progress -Id 0 -Activity 'Running scripts to customize your Windows installation. Do not close this window.' -PercentComplete $complete;
    '*** Will now execute command «{0}».' -f $(
      $script.ToString().Trim() -replace '\s+', ' ' -replace '^(.{99})(.+)$', '$1…';
    );
    $start = [datetime]::Now;
    & $script;
    '*** Finished executing command after {0:0} ms.' -f [datetime]::Now.Subtract( $start ).TotalMilliseconds;
    "`r`n" * 3;
    $complete += $increment;
  }
} *>&1 | Out-String -Width 1KB -Stream >> "C:\Windows\Setup\Scripts\Specialize.log";

# Settings written directly to C:\Users\Default\NTUSER.DAT (mounted at HKU\DefaultUser).
$scripts = @(
	{
		# Disable Windows Copilot in the default user profile.
		reg.exe add "HKU\DefaultUser\Software\Policies\Microsoft\Windows\WindowsCopilot" /v TurnOffWindowsCopilot /t REG_DWORD /d 1 /f;
	};
	{
		# Prevent OneDriveSetup from launching automatically on first logon for any new user.
		Remove-ItemProperty -LiteralPath 'Registry::HKU\DefaultUser\Software\Microsoft\Windows\CurrentVersion\Run' -Name 'OneDriveSetup' -Force -ErrorAction 'SilentlyContinue';
	};
	{
		# Disable Xbox Game DVR background recording (0 = Off, 1 = On).
		reg.exe add "HKU\DefaultUser\Software\Microsoft\Windows\CurrentVersion\GameDVR" /v AppCaptureEnabled /t REG_DWORD /d 0 /f;
	};
	{
		# File Explorer defaults and app launch tracking:
		#   HideFileExt      : 0 = Show file extensions | 1 = Hide extensions
		#   Hidden           : 2 = Hide hidden files    | 1 = Show hidden files
		#   ShowSuperHidden  : 0 = Hide protected OS    | 1 = Show protected OS files
		#   Start_TrackProgs : 1 = Track app launches (required for 'Top apps' in Search)
		reg.exe add "HKU\DefaultUser\Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced" /v "HideFileExt" /t REG_DWORD /d 0 /f;
		reg.exe add "HKU\DefaultUser\Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced" /v "Hidden" /t REG_DWORD /d 2 /f;
		reg.exe add "HKU\DefaultUser\Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced" /v "ShowSuperHidden" /t REG_DWORD /d 0 /f;
		reg.exe add "HKU\DefaultUser\Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced" /v "Start_TrackProgs" /t REG_DWORD /d 1 /f;
	};
	{
		# Pre-enable taskbar Search icon, Bing Search, Quick Searches (Search Highlights), and Device Search History.
		reg.exe add "HKU\DefaultUser\Software\Microsoft\Windows\CurrentVersion\Search" /v "SearchboxTaskbarMode" /t REG_DWORD /d 1 /f;
		reg.exe add "HKU\DefaultUser\Software\Microsoft\Windows\CurrentVersion\Search" /v "BingSearchEnabled" /t REG_DWORD /d 1 /f;
		reg.exe add "HKU\DefaultUser\Software\Microsoft\Windows\CurrentVersion\SearchSettings" /v "IsDynamicSearchBoxEnabled" /t REG_DWORD /d 1 /f;
		reg.exe add "HKU\DefaultUser\Software\Microsoft\Windows\CurrentVersion\SearchSettings" /v "IsDeviceSearchHistoryEnabled" /t REG_DWORD /d 1 /f;
	};
	{
		# Block silent installation of promotional / sponsored Store apps on Home edition.
		# Note: ContentDeliveryAllowed is intentionally left untouched so dynamic Search content is not suppressed.
		reg.exe add "HKU\DefaultUser\Software\Microsoft\Windows\CurrentVersion\ContentDeliveryManager" /v "SilentInstalledAppsEnabled" /t REG_DWORD /d 0 /f;
		reg.exe add "HKU\DefaultUser\Software\Microsoft\Windows\CurrentVersion\ContentDeliveryManager" /v "PreInstalledAppsEnabled" /t REG_DWORD /d 0 /f;
		reg.exe add "HKU\DefaultUser\Software\Microsoft\Windows\CurrentVersion\ContentDeliveryManager" /v "OemPreInstalledAppsEnabled" /t REG_DWORD /d 0 /f;
	};
	{
		# Schedule UserOnce.ps1 to run automatically once at each new user's first sign-in.
		$runOncePath = 'Registry::HKU\DefaultUser\Software\Microsoft\Windows\CurrentVersion\RunOnce';
		if( -not ( Test-Path -LiteralPath $runOncePath ) ) {
			New-Item -Path $runOncePath -Force | Out-Null;
		}
		Set-ItemProperty -LiteralPath $runOncePath -Name 'UnattendedSetup' -Type 'String' -Value 'powershell.exe -WindowStyle "Hidden" -ExecutionPolicy "Unrestricted" -NoProfile -File "C:\Windows\Setup\Scripts\UserOnce.ps1"' -Force;
	};
);

# Execute each block with timing and capture all streams to DefaultUser.log.
& {
  [float] $complete = 0;
  [float] $increment = 100 / $scripts.Count;
  foreach( $script in $scripts ) {
    Write-Progress -Id 0 -Activity 'Running scripts to modify the Default User registry hive. Do not close this window.' -PercentComplete $complete;
    '*** Will now execute command «{0}».' -f $(
      $script.ToString().Trim() -replace '\s+', ' ' -replace '^(.{99})(.+)$', '$1…';
    );
    $start = [datetime]::Now;
    & $script;
    '*** Finished executing command after {0:0} ms.' -f [datetime]::Now.Subtract( $start ).TotalMilliseconds;
    "`r`n" * 3;
    $complete += $increment;
  }
} *>&1 | Out-String -Width 1KB -Stream >> "C:\Windows\Setup\Scripts\DefaultUser.log";

# Per-user tweaks executed once on first desktop sign-in via HKCU RunOnce.
$scripts = @(
	# =========================================================================
	# 1. PER-USER APP CLEANUP
	# =========================================================================
	{
		# Remove the per-user Copilot AI provider package if registered during profile creation.
		Get-AppxPackage -Name 'Microsoft.Windows.Ai.Copilot.Provider' -ErrorAction 'SilentlyContinue' | Remove-AppxPackage -ErrorAction 'SilentlyContinue';
	};

	# =========================================================================
	# 2. FILE EXPLORER (MODERN WINDOWS 11 CONTEXT MENU KEPT INTACT)
	# =========================================================================
	{
		# Set File Explorer default start page (1 = This PC, 2 = Home/Quick Access, 3 = Downloads),
		# enforce visibility rules, and keep app launch tracking enabled for 'Top apps' in Search.
		reg.exe add "HKCU\Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced" /v LaunchTo /t REG_DWORD /d 1 /f;
		reg.exe add "HKCU\Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced" /v HideFileExt /t REG_DWORD /d 0 /f;
		reg.exe add "HKCU\Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced" /v Hidden /t REG_DWORD /d 2 /f;
		reg.exe add "HKCU\Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced" /v ShowSuperHidden /t REG_DWORD /d 0 /f;
		reg.exe add "HKCU\Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced" /v Start_TrackProgs /t REG_DWORD /d 1 /f;
	};

	# =========================================================================
	# 3. TASKBAR, SEARCH AND START MENU
	# =========================================================================
	{
		# Taskbar Search appearance (0 = Hidden, 1 = Search icon only, 2 = Search box, 3 = Search icon + label),
		# plus Bing Search, Quick Searches (Search Highlights), and Device Search History (1 = On, 0 = Off).
		reg.exe add "HKCU\Software\Microsoft\Windows\CurrentVersion\Search" /v SearchboxTaskbarMode /t REG_DWORD /d 1 /f;
		reg.exe add "HKCU\Software\Microsoft\Windows\CurrentVersion\Search" /v BingSearchEnabled /t REG_DWORD /d 1 /f;
		reg.exe add "HKCU\Software\Microsoft\Windows\CurrentVersion\SearchSettings" /v IsDynamicSearchBoxEnabled /t REG_DWORD /d 1 /f;
		reg.exe add "HKCU\Software\Microsoft\Windows\CurrentVersion\SearchSettings" /v IsDeviceSearchHistoryEnabled /t REG_DWORD /d 1 /f;
	};
	{
		# Configure quick-access folder icons shown next to the Power button in Start Menu (binary list of 7 folder GUIDs).
		$startKeyPath = 'Registry::HKEY_CURRENT_USER\Software\Microsoft\Windows\CurrentVersion\Start';
		if( -not ( Test-Path -LiteralPath $startKeyPath ) ) {
			New-Item -Path $startKeyPath -Force | Out-Null;
		}
		Set-ItemProperty -LiteralPath $startKeyPath -Name 'VisiblePlaces' -Value $( [convert]::FromBase64String('ztU0LVr6Q0WC8iLm6vd3PC+zZ+PeiVVDv85h83sYqTe8JIoUDNaJQqCAbtm7okiCRIF1/g0IrkKL2jTtl7ZjlEqwvXRK+WhPi9ZDmAcdqLygBz84CuiATLBahtuEXbxNhghzUqpRQ0Kfeyd2WEZZ1A==') ) -Type 'Binary' -Force;
	};
	{
		# Hide the legacy Chat (Teams) button on the taskbar (0 = Hidden).
		# Note: Widgets button is already disabled machine-wide via AllowNewsAndInterests = 0 in Specialize.ps1.
		reg.exe add "HKCU\Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced" /v TaskbarMn /t REG_DWORD /d 0 /f;
	};
	{
		# Disable Start Menu tips, shortcuts, and new-app recommendations (0 = Off).
		reg.exe add "HKCU\Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced" /v Start_IrisRecommendations /t REG_DWORD /d 0 /f;
	};

	# =========================================================================
	# 4. PER-USER PRIVACY, ADS AND SUGGESTIONS
	# =========================================================================
	{
		# Disable Start Menu suggestions, lock-screen tips, and silent/sponsored app installations.
		# Note: ContentDeliveryAllowed is intentionally omitted so Search Highlights / Quick Searches continue working.
		reg.exe add "HKCU\Software\Microsoft\Windows\CurrentVersion\ContentDeliveryManager" /v SystemPaneSuggestionsEnabled /t REG_DWORD /d 0 /f;
		reg.exe add "HKCU\Software\Microsoft\Windows\CurrentVersion\ContentDeliveryManager" /v SoftLandingEnabled /t REG_DWORD /d 0 /f;
		reg.exe add "HKCU\Software\Microsoft\Windows\CurrentVersion\ContentDeliveryManager" /v SilentInstalledAppsEnabled /t REG_DWORD /d 0 /f;
		reg.exe add "HKCU\Software\Microsoft\Windows\CurrentVersion\ContentDeliveryManager" /v PreInstalledAppsEnabled /t REG_DWORD /d 0 /f;
		reg.exe add "HKCU\Software\Microsoft\Windows\CurrentVersion\ContentDeliveryManager" /v OemPreInstalledAppsEnabled /t REG_DWORD /d 0 /f;
		reg.exe add "HKCU\Software\Microsoft\Windows\CurrentVersion\ContentDeliveryManager" /v SubscribedContent-338387Enabled /t REG_DWORD /d 0 /f;
		reg.exe add "HKCU\Software\Microsoft\Windows\CurrentVersion\ContentDeliveryManager" /v SubscribedContent-338388Enabled /t REG_DWORD /d 0 /f;
		reg.exe add "HKCU\Software\Microsoft\Windows\CurrentVersion\ContentDeliveryManager" /v SubscribedContent-338389Enabled /t REG_DWORD /d 0 /f;
		reg.exe add "HKCU\Software\Microsoft\Windows\CurrentVersion\ContentDeliveryManager" /v SubscribedContent-310093Enabled /t REG_DWORD /d 0 /f;
		reg.exe add "HKCU\Software\Microsoft\Windows\CurrentVersion\ContentDeliveryManager" /v SubscribedContent-353694Enabled /t REG_DWORD /d 0 /f;
		reg.exe add "HKCU\Software\Microsoft\Windows\CurrentVersion\ContentDeliveryManager" /v SubscribedContent-353696Enabled /t REG_DWORD /d 0 /f;
	};
	{
		# Suppress the "Let's finish setting up your device" (SCOOBE) full-screen nag prompt.
		reg.exe add "HKCU\Software\Microsoft\Windows\CurrentVersion\UserProfileEngagement" /v ScoobeSystemSettingEnabled /t REG_DWORD /d 0 /f;
	};
	{
		# Disable per-user Advertising ID and diagnostic-based tailored experiences.
		reg.exe add "HKCU\Software\Microsoft\Windows\CurrentVersion\AdvertisingInfo" /v Enabled /t REG_DWORD /d 0 /f;
		reg.exe add "HKCU\Software\Microsoft\Windows\CurrentVersion\Privacy" /v TailoredExperiencesWithDiagnosticDataEnabled /t REG_DWORD /d 0 /f;
	};

	# =========================================================================
	# 5. REGIONAL LOCATION AND SHELL REFRESH
	# =========================================================================
	{
		# Set Windows Country/Region to United States (GeoID 244) so Bing Quick Searches reliably appear.
		# Change 244 to 23 if you prefer Country/Region set to Bangladesh (TimeZone remains Dhaka UTC+06:00).
		try { Set-WinHomeLocation -GeoId 244 } catch { }
	};
	{
		# Restart Explorer, SearchHost, and StartMenuExperienceHost in the current session so tweaks apply immediately.
		$currentSessionId = ( Get-Process -Id $PID ).SessionId;
		Get-Process -Name 'explorer', 'SearchHost', 'StartMenuExperienceHost' -ErrorAction 'SilentlyContinue' | Where-Object -FilterScript {
			$_.SessionId -eq $currentSessionId;
		} | Stop-Process -Force -ErrorAction 'SilentlyContinue';
	};
);

# Execute each block with timing and capture all streams to %TEMP%\UserOnce.log.
& {
  [float] $complete = 0;
  [float] $increment = 100 / $scripts.Count;
  foreach( $script in $scripts ) {
    Write-Progress -Id 0 -Activity 'Running scripts to configure this user account. Do not close this window.' -PercentComplete $complete;
    '*** Will now execute command «{0}».' -f $(
      $script.ToString().Trim() -replace '\s+', ' ' -replace '^(.{99})(.+)$', '$1…';
    );
    $start = [datetime]::Now;
    & $script;
    '*** Finished executing command after {0:0} ms.' -f [datetime]::Now.Subtract( $start ).TotalMilliseconds;
    "`r`n" * 3;
    $complete += $increment;
  }
} *>&1 | Out-String -Width 1KB -Stream >> "$env:TEMP\UserOnce.log";

# Elevated system-level tasks executed once during the first administrator sign-in.
# Tip: You can add custom post-install commands (e.g., winget installs or WSL setup) below.
$scripts = @(
	{
		# Safeguard: ensure AutoLogonCount is reset to 0 after initial setup completes.
		Set-ItemProperty -LiteralPath 'Registry::HKLM\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Winlogon' -Name 'AutoLogonCount' -Type 'DWord' -Force -Value 0;
	};
);

# Execute each block with timing and capture all streams to FirstLogon.log.
& {
  [float] $complete = 0;
  [float] $increment = 100 / $scripts.Count;
  foreach( $script in $scripts ) {
    Write-Progress -Id 0 -Activity 'Running scripts to finalize your Windows installation. Do not close this window.' -PercentComplete $complete;
    '*** Will now execute command «{0}».' -f $(
      $script.ToString().Trim() -replace '\s+', ' ' -replace '^(.{99})(.+)$', '$1…';
    );
    $start = [datetime]::Now;
    & $script;
    '*** Finished executing command after {0:0} ms.' -f [datetime]::Now.Subtract( $start ).TotalMilliseconds;
    "`r`n" * 3;
    $complete += $increment;
  }
} *>&1 | Out-String -Width 1KB -Stream >> "C:\Windows\Setup\Scripts\FirstLogon.log";
